sys_ux_client_script.script:
/**
 * Evaluates and returns an element or element_level2 value based on conditions.
 *
 * This function determines whether to retrieve data from the daily or monthly frequency list
 * based on the provided index `i`. If `i` is within the daily frequency range, the corresponding
 * daily result is returned. If `i` exceeds the daily frequency length, the function calculates 
 * an adjusted index `k` to retrieve the next available non-intersecting value from the monthly frequency.
 *
 * @param {Object} params - The function parameters.
 * @param {Object} params.api - API object containing data and state.
 * @param {number} params.i - Index value provided.
 * @returns {string|null} - The corresponding element or element_level2 value, or null if waiting for instructions.
 */
function evaluateProperty({ api, i = 4 }) {
    const clientStateParameter = api.state.Tab11stBreakdown;

    // Get daily and monthly frequency lists
    const dailyFrequency = api.state.elementsDeploymentFrequencyDaily;
    const monthlyFrequency = api.state.elementsDeploymentFrequencyMonthly;

    // Get their lengths
    const dailyLength = dailyFrequency.length;
    const monthlyLength = monthlyFrequency.length;

    // Step 1: Retrieve from daily frequency if i is within bounds
    if (i < dailyLength) {
        const dailyResult = api.data.verticalC_headlinemetric2_daily.output.result[i];
        return clientStateParameter === ''
            ? dailyResult?.element.display_value
            : dailyResult?.element_level2.display_value;
    }

    // Step 2: Generate a mask marking intersections (1 for match, 0 for non-match)
    const intersectionMask = monthlyFrequency.map(pis => dailyFrequency.includes(pis) ? 1 : 0);

    // Step 3: Extract valid indices (only non-matching elements)
    const validKIndices = intersectionMask
        .map((match, idx) => (match === 0 ? idx : -1))
        .filter(idx => idx !== -1);

    // Compute adjusted index k for non-intersecting monthly values
    const kIndex = i - dailyLength;

    // Step 4: Ensure kIndex remains within valid indices
    if (kIndex < validKIndices.length) {
        const k = validKIndices[kIndex];
        const monthlyResult = api.data.verticalC_headlinemetric2_monthly.output.result[k];

        return clientStateParameter === ''
            ? monthlyResult?.element.display_value
            : monthlyResult?.element_level2.display_value;
    }

    // Step 5: If i exceeds available data, return null (wait for instructions)
    return null;
}
